// V188.103: every OpenAI-compatible text model can be attempted in both
// streaming and non-streaming transport modes. High-intelligence reasoning
// requests prefer streaming so Telegram can surface output while the model is
// still generating instead of waiting for the full response body.
const HIGH_INTELLIGENCE_STREAM_EFFORTS = new Set(['high', 'xhigh', 'max']);
const TELEGRAM_STREAM_EDIT_INTERVAL_MS = clampInteger(
    process.env.TELEGRAM_STREAM_EDIT_INTERVAL_MS,
    500,
    3000,
    900,
);
const TELEGRAM_STREAM_FIRST_FLUSH_MS = clampInteger(
    process.env.TELEGRAM_STREAM_FIRST_FLUSH_MS,
    100,
    1500,
    300,
);
const TELEGRAM_STREAM_MIN_DELTA_CHARS = clampInteger(
    process.env.TELEGRAM_STREAM_MIN_DELTA_CHARS,
    16,
    512,
    72,
);
const TELEGRAM_STREAM_MESSAGE_LIMIT = 3900;

function isHighIntelligenceReasoningEffort(value) {
    return HIGH_INTELLIGENCE_STREAM_EFFORTS.has(
        String(value ?? '').trim().toLowerCase(),
    );
}

function getReasoningSafeMaxTokens(maxTokens, reasoningEffort, model = '') {
    const requested = Number(maxTokens);
    const base = Number.isSafeInteger(requested) && requested > 0 ? requested : 0;
    const effort = String(reasoningEffort ?? '').trim().toLowerCase();
    if (!isHighIntelligenceReasoningEffort(effort)) return base || maxTokens;

    // Responses counts hidden reasoning inside max_output_tokens. A short visible
    // answer profile can otherwise be exhausted entirely by high/xhigh/max
    // reasoning, producing usage with reasoning_tokens > 0 but text_tokens = 0.
    const floor = isAstraModel(model) || effort === 'max'
        ? 8_000
        : effort === 'xhigh'
            ? 6_000
            : 4_000;
    return Math.max(base, floor);
}

function splitTelegramStreamingText(value, limit = TELEGRAM_STREAM_MESSAGE_LIMIT) {
    // Preserve whitespace and Unicode boundaries; never silently discard part of the answer.
    return splitTelegramLongReply(String(value ?? ''), Math.min(3500, limit));
}

function createTelegramTextStreamSession(context) {
    const rawContext = getRawContext(context);
    if (String(rawContext?.platform ?? '').toLowerCase() !== 'telegram') return null;

    const api = rawContext?.telegramApi;
    if (!api || typeof api.sendMessage !== 'function' || typeof api.editMessageText !== 'function') {
        return null;
    }

    const chatId = String(rawContext?.externalPeerId ?? '').trim();
    if (!chatId) return null;

    const messageThreadId = Number(rawContext?.telegramMessageThreadId ?? 0) || null;
    const replyToMessageId = Number(rawContext?.conversationMessageId ?? 0) || null;
    let text = '';
    let renderedChunks = [];
    const messageIds = [];
    let editChain = Promise.resolve();
    let timer = null;
    let closed = false;
    let failed = false;
    let lastFlushAt = 0;
    let charsAtLastFlush = 0;

    const logFailure = (error) => {
        const message = String(error?.message ?? error);
        if (/message is not modified/iu.test(message)) return;
        failed = true;
        console.warn('[TELEGRAM GPT STREAM EDIT ERROR]', formatPrivateError(error));
    };

    const syncNow = async () => {
        if (failed) return;
        const chunks = splitTelegramStreamingText(text);
        if (!chunks.length) return;

        for (let index = 0; index < chunks.length; index += 1) {
            const chunk = chunks[index];
            if (!messageIds[index]) {
                console.info('[TELEGRAM GPT STREAM PART START]', `part=${index + 1}/${chunks.length}`, `chars=${chunk.length}`);
                const sent = await api.sendMessage({
                    chatId,
                    text: chunk,
                    messageThreadId,
                    replyToMessageId: index === 0 ? replyToMessageId : null,
                });
                const messageId = Number(sent?.message_id ?? 0) || 0;
                if (!messageId) {
                    throw new Error('Telegram stream sendMessage did not return message_id.');
                }
                messageIds[index] = messageId;
                console.info('[TELEGRAM GPT STREAM PART SENT]', `part=${index + 1}/${chunks.length}`, `chars=${chunk.length}`, `messageId=${messageId}`);
            } else if (renderedChunks[index] !== chunk) {
                try {
                    await api.editMessageText({
                        chatId,
                        messageId: messageIds[index],
                        text: chunk,
                    });
                    console.info('[TELEGRAM GPT STREAM PART EDITED]', `part=${index + 1}/${chunks.length}`, `chars=${chunk.length}`, `messageId=${messageIds[index]}`);
                } catch (error) {
                    if (!/message is not modified/iu.test(String(error?.message ?? error))) {
                        throw error;
                    }
                }
            }
        }

        if (messageIds.length > chunks.length && typeof api.deleteMessage === 'function') {
            for (let index = messageIds.length - 1; index >= chunks.length; index -= 1) {
                const staleMessageId = messageIds[index];
                if (!staleMessageId) continue;
                try {
                    await api.deleteMessage({ chatId, messageId: staleMessageId });
                } catch (error) {
                    console.warn(
                        '[TELEGRAM GPT STREAM DELETE WARNING]',
                        `messageId=${staleMessageId}`,
                        formatPrivateError(error),
                    );
                }
                messageIds.splice(index, 1);
            }
        }

        renderedChunks = chunks;
        lastFlushAt = Date.now();
        charsAtLastFlush = text.length;
    };

    const queueSync = () => {
        editChain = editChain
            .then(syncNow)
            .catch(logFailure);
        return editChain;
    };

    const scheduleSync = () => {
        if (closed || failed || timer) return;
        const first = messageIds.length === 0;
        const elapsed = Math.max(0, Date.now() - lastFlushAt);
        const targetDelay = first
            ? TELEGRAM_STREAM_FIRST_FLUSH_MS
            : Math.max(0, TELEGRAM_STREAM_EDIT_INTERVAL_MS - elapsed);
        timer = setTimeout(() => {
            timer = null;
            void queueSync();
        }, targetDelay);
        timer.unref?.();
    };

    return {
        push(delta) {
            if (closed || failed) return;
            const chunk = String(delta ?? '');
            if (!chunk) return;
            text += chunk;
            const pendingChars = text.length - charsAtLastFlush;
            if (messageIds.length === 0 || pendingChars >= TELEGRAM_STREAM_MIN_DELTA_CHARS) {
                scheduleSync();
            }
        },
        reset() {
            if (closed || failed) return;
            if (timer) {
                clearTimeout(timer);
                timer = null;
            }
            text = '';
            renderedChunks = [];
            charsAtLastFlush = 0;
        },
        async finalize(finalText) {
            closed = true;
            if (timer) {
                clearTimeout(timer);
                timer = null;
            }
            const normalized = String(finalText ?? '');
            if (normalized.trim()) text = normalized;
            await queueSync();
            await editChain;
            return {
                handled: messageIds.length > 0 && !failed,
                sentAny: messageIds.length > 0,
                failed,
                messageIds: [...messageIds],
            };
        },
        async drain() {
            if (timer) {
                clearTimeout(timer);
                timer = null;
            }
            await queueSync();
            await editChain;
        },
        get sentAny() {
            return messageIds.length > 0;
        },
        get failed() {
            return failed;
        },
    };
}
