function combineAbortSignals(signals) {
    const activeSignals = (Array.isArray(signals) ? signals : [])
        .filter(Boolean);
    if (!activeSignals.length) return undefined;
    if (activeSignals.length === 1) return activeSignals[0];
    if (typeof AbortSignal.any === 'function') {
        return AbortSignal.any(activeSignals);
    }

    const controller = new AbortController();
    const abortFrom = (signal) => {
        if (!controller.signal.aborted) {
            controller.abort(signal?.reason);
        }
    };
    for (const signal of activeSignals) {
        if (signal.aborted) {
            abortFrom(signal);
            break;
        }
        signal.addEventListener('abort', () => abortFrom(signal), { once: true });
    }
    return controller.signal;
}

function buildOperationAbortSignal(timeoutMs) {
    const localSignal = AbortSignal.timeout(
        Math.max(1_000, Number(timeoutMs) || DEFAULT_OPERATION_TIMEOUT_MS),
    );
    return combineAbortSignals([localSignal, getCurrentOperationSignal()]);
}

function createIdleAbortWatchdog(timeoutMs, label = 'stream') {
    const controller = new AbortController();
    const safeTimeoutMs = Math.max(30_000, Number(timeoutMs) || 30 * 60 * 1000);
    let timer = null;
    const touch = () => {
        if (controller.signal.aborted) return;
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            if (!controller.signal.aborted) {
                controller.abort(new DOMException(
                    `${label} produced no bytes for ${safeTimeoutMs} ms`,
                    'TimeoutError',
                ));
            }
        }, safeTimeoutMs);
        timer.unref?.();
    };
    const dispose = () => {
        if (timer) clearTimeout(timer);
        timer = null;
    };
    touch();
    return { signal: controller.signal, touch, dispose };
}

function runDetachedSupervisedOperation({
    name,
    category = 'background',
    metadata = {},
    timeoutMs = DEFAULT_OPERATION_TIMEOUT_MS,
} = {}, task) {
    const promise = runSupervisedOperation({
        name,
        category,
        metadata,
        timeoutMs,
    }, task);
    void promise.catch((error) => {
        auditRuntimeEvent('operation.detached.rejected', {
            name,
            category,
            error: formatPrivateError(error),
        }, { level: 'error' });
        console.error(
            '[SUPERVISED DETACHED OPERATION ERROR]',
            `name=${String(name || 'unknown')}`,
            formatPrivateError(error),
        );
    });
    return promise;
}

