function collectGigaChatCredentialEntries() {
    const entries = [];
    const seen = new Set();
    const push = (name, value) => {
        const secret = String(value ?? '').trim();
        if (!secret || seen.has(secret)) return;
        seen.add(secret);
        entries.push({ name, secret });
    };
    push('GIGACHAT_CREDENTIALS', process.env.GIGACHAT_CREDENTIALS);
    for (let index = 1; index <= 20; index += 1) {
        push(`GIGACHAT_CREDENTIALS_${index}`, process.env[`GIGACHAT_CREDENTIALS_${index}`]);
    }
    return entries;
}



/**
 * Командный текст в группе может находиться до/после обращения «Гигорейв»,
 * но обращение действует только внутри того же предложения. Для сообщений
 * без обращения сохраняем прежнее standalone-поведение локальных fast-path.
 */
function getIncomingCommandCandidates(value) {
    const source = String(value ?? '').trim();
    if (!source) return [];

    if (containsBotMention(source)) {
        return getBotAddressedCommandCandidates(source);
    }

    const stripped = String(removeBotMentions(source) || source).trim();
    return stripped ? [stripped] : [];
}

function parseCommandCandidateList(values, parser, isMatch = null) {
    const matcher = typeof isMatch === 'function'
        ? isMatch
        : (parsed) => Boolean(parsed?.matched ?? parsed);
    const candidates = [...new Set(
        (Array.isArray(values) ? values : [values])
            .map((value) => String(value ?? '').trim())
            .filter(Boolean),
    )];

    for (const commandText of candidates) {
        const parsed = parser(commandText);
        if (matcher(parsed)) {
            return { matched: true, commandText, parsed };
        }
    }

    return { matched: false, commandText: '', parsed: null };
}

function parseIncomingCommand(value, parser, isMatch = null) {
    return parseCommandCandidateList(
        getIncomingCommandCandidates(value),
        parser,
        isMatch,
    );
}

function resolveIncomingCommandPriority(value, options = {}) {
    const candidates = getIncomingCommandCandidates(value);
    return candidates.length
        ? resolveCommandPriorityCandidates(candidates, options)
        : resolveCommandPriority('', options);
}

/**
 * Единый дешёвый детектор явной команды для pending-state fast-paths.
 * Он нужен не для выполнения команды, а чтобы незавершённый ввод (QR,
 * предложка, отзыв и т.п.) не проглотил команду до основного router.
 */
function detectExplicitIncomingCommand(value) {
    const candidates = getIncomingCommandCandidates(value);
    if (!candidates.length) {
        return { matched: false, family: '', candidates: [] };
    }

    const routeDecision = resolveCommandPriorityCandidates(candidates, {
        parsePublicEventsRangeCommand,
        looksLikePublicEventsQuestion,
    });
    if (!['default', 'public-events-semantic'].includes(routeDecision.route)) {
        return {
            matched: true,
            family: `route:${routeDecision.route}`,
            commandText: routeDecision.requestText,
            parsed: routeDecision.selected,
            candidates,
        };
    }

    const checks = [
        ['auto-summary', parseAutoSummaryCommand, (parsed) => Boolean(parsed?.matched)],
        ['vk-history-pull', parseVkHistoryPullCommand, (parsed) => Boolean(parsed?.matched)],
        ['chat-history-link', parseChatHistoryLinkCommand, (parsed) => Boolean(parsed?.matched)],
        ['leavers', parseLeaverCommand, (parsed) => Boolean(parsed?.matched)],
        ['participant-dm-broadcast', parseParticipantDmBroadcastCommand, (parsed) => Boolean(parsed?.matched)],
        ['service-events-report', parseServiceEventsReportCommand, Boolean],
        ['qr-code', parseQrCodeCommand, (parsed) => Boolean(parsed?.matched)],
        ['coords', parseCoordsOverrideCommand, (parsed) => Boolean(parsed?.matched)],
        ['event-moderation', parseEventModerationCommand, Boolean],
        ['bot-request-stats', parseBotRequestStatsCommand, Boolean],
        ['event-proposal', (candidate) => {
            const body = parseEventProposalCommand(candidate);
            return { matched: body !== null, body };
        }, (parsed) => Boolean(parsed?.matched)],
    ];

    for (const [family, parser, matcher] of checks) {
        const match = parseCommandCandidateList(candidates, parser, matcher);
        if (match.matched) {
            return {
                matched: true,
                family,
                commandText: match.commandText,
                parsed: match.parsed,
                candidates,
            };
        }
    }

    return { matched: false, family: '', candidates };
}

function isGlobalInteractionCancelCommand(value) {
    return getIncomingCommandCandidates(value).some((candidate) =>
        /^(?:отмена|отменить|отмени|cancel|стоп|сброс(?:ить)?(?:\s+режим)?|выйти)$/iu.test(
            String(candidate ?? '').trim(),
        ),
    );
}

function clearPendingInteractionState(context) {
    const stateKey = getCoordsOwnerInputKey(context);
    let cleared = 0;
    for (const store of [
        pendingCoordsMessageInputs,
        pendingCoordsBroadcastInputs,
        pendingPeresozdanieBroadcastInputs,
        pendingQrCodeInputs,
        pendingEventProposalInputs,
        pendingManualEventUpdates,
        pendingEventDeletionConfirmations,
        pendingEventModerationSelections,
        pendingEventEditInputs,
    ]) {
        if (store.delete(stateKey)) cleared += 1;
    }

    if (sessions.delete(participantKey(context))) {
        cleared += 1;
    }

    const feedbackRecipient = getPostEventFeedbackEndpoint(context);
    if (feedbackRecipient && cancelPostEventFeedbackRequest({
        campaignKey: PERESOZDANIE_FEEDBACK_CAMPAIGN_KEY,
        ...feedbackRecipient,
    })) {
        cleared += 1;
    }

    return cleared;
}

async function maybeHandleGlobalInteractionCancel(context, value) {
    if (!isGlobalInteractionCancelCommand(value)) return false;

    const cleared = clearPendingInteractionState(context);
    await context.send(
        cleared
            ? 'Текущее действие отменено. Можно сразу отправлять новую команду.'
            : 'Активного режима ожидания нет. Можно отправлять новую команду.',
    );
    return true;
}

