// batches. /files is available only after an explicit operator opt-in to file.
const PROJECT_ARCHIVE_INPUT_MODE = (() => {
    const value = String(process.env.PROJECT_ARCHIVE_INPUT_MODE || 'text').trim().toLowerCase();
    return value === 'file' ? 'file' : 'text';
})();
const PROJECT_ARCHIVE_AUDIT_MULTIPASS_ENABLED = PROJECT_ARCHIVE_INPUT_MODE === 'text' ||
    /^(?:1|true|yes|on)$/iu.test(String(process.env.PROJECT_ARCHIVE_AUDIT_MULTIPASS || '').trim());
// Even a stale background/auto setting must not override the text transport.
const PROJECT_ARCHIVE_MULTIPASS_TRANSPORT = (() => {
    const value = String(process.env.PROJECT_ARCHIVE_MULTIPASS_TRANSPORT || 'stream').trim().toLowerCase();
    if (PROJECT_ARCHIVE_INPUT_MODE === 'text') return 'stream';
    return value === 'background' ? 'background' : 'stream';
})();
function shouldUseProjectArchiveTextMultipass() {
    // Explicit file mode takes priority over the legacy MULTIPASS toggle.
    return PROJECT_ARCHIVE_INPUT_MODE !== 'file' && PROJECT_ARCHIVE_AUDIT_MULTIPASS_ENABLED;
}
